    Ry(2.0 * ArcSin(Sqrt(1.0/IntAsDouble(N))), qs[0]);
    for i in 1 .. N - 1 {
        (ControlledOnInt(0, Ry(2.0 * ArcSin(Sqrt(1.0/IntAsDouble(N - i))), _)))(qs[0 .. i-1], qs[i]);
    }
}

